// ---------------------------------------------------------------- MRZ (ICAO 9303, computed in code)
const MVAL: Record<string, number> = {};
"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("").forEach((c, i) => (MVAL[c] = i));
MVAL["<"] = 0;
function mrzCheck(s: string): number {
  let tot = 0;
  for (let i = 0; i < s.length; i++) tot += MVAL[s[i]] * [7, 3, 1][i % 3];
  return tot % 10;
}
const DOC = "CD0417882", DOB = "850612", EXP = "360302", NAT = "CDA";
const cDoc = mrzCheck(DOC), cDob = mrzCheck(DOB), cExp = mrzCheck(EXP);
const OPT = "<".repeat(14), cOpt = mrzCheck(OPT);
const cComp = mrzCheck(DOC + cDoc + DOB + cDob + EXP + cExp + OPT + cOpt);
const MRZ1 = ("P<CDA" + "MORVEK<<DAIN").padEnd(44, "<");
const MRZ2 = `${DOC}${cDoc}${NAT}${DOB}${cDob}M${EXP}${cExp}${OPT}${cOpt}${cComp}`;
if (MRZ1 !== "P<CDAMORVEK<<DAIN<<<<<<<<<<<<<<<<<<<<<<<<<<<" ||
    MRZ2 !== "CD04178823CDA8506128M3603022<<<<<<<<<<<<<<06") {
  console.error("MRZ mismatch", MRZ1, MRZ2);
  process.exit(1);
}

