// Stamps (distressed, rotated)
function roundStamp(cx: number, cy: number, r: number, c: RGB, ang: number, lines: string[]) {
  inkSkip = 0.10;
  circle(cx, cy, r, c, 2.5); circle(cx, cy, r * 0.78, c, 1.5);
  const step = 22;
  const y0 = cy - ((lines.length - 1) * step) / 2;
  lines.forEach((l, i) => textRot(l, cx, y0 + i * step, ang, AB, c, 0.72));
  inkSkip = 0;
}
function rectStamp(cx: number, cy: number, w: number, h: number, c: RGB, ang: number, lines: string[]) {
  inkSkip = 0.10;
  const rad = (ang * Math.PI) / 180, co = Math.cos(rad), si = Math.sin(rad);
  const corner = (sx: number, sy: number): [number, number] =>
    [cx + sx * co - sy * si, cy + sx * si + sy * co];
  const [ax, ay] = corner(-w / 2, -h / 2), [bx, by] = corner(w / 2, -h / 2);
  const [ccx, ccy] = corner(w / 2, h / 2), [dx, dy] = corner(-w / 2, h / 2);
  line(ax, ay, bx, by, c, 2); line(bx, by, ccx, ccy, c, 2);
  line(ccx, ccy, dx, dy, c, 2); line(dx, dy, ax, ay, c, 2);
  const step = 22;
  const y0 = cy - ((lines.length - 1) * step) / 2;
  lines.forEach((l, i) => textRot(l, cx, y0 + i * step, ang, AB, c, 0.8));
  inkSkip = 0;
}
